/**
 * Copies the founding markdown files into convex/knowledge/ as TypeScript
 * string modules, byte-for-byte, so Convex functions (which cannot read the
 * filesystem at runtime) can parse and ingest them. The markdown stays the
 * single source of truth — these generated files are never edited by hand.
 *
 * Run before seeding: node scripts/sync-knowledge.mjs
 */
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const outDir = join(root, "convex", "knowledge");
mkdirSync(outDir, { recursive: true });

const files = [
  ["project-archetypes.md", "projectArchetypes"],
  ["coaching-transcripts.md", "coachingTranscripts"],
  ["scope-examples.md", "scopeExamples"],
  ["milestone-zero-examples.md", "milestoneZeroExamples"],
];

for (const [file, name] of files) {
  const content = readFileSync(join(root, file), "utf8");
  const out =
    `// GENERATED by scripts/sync-knowledge.mjs from ${file} — do not edit.\n` +
    `const ${name} = ${JSON.stringify(content)};\n` +
    `export default ${name};\n`;
  writeFileSync(join(outDir, `${name}.ts`), out);
  console.log(`synced ${file} -> convex/knowledge/${name}.ts (${content.length} chars)`);
}
